<?php require __DIR__.'/bootstrap.php';messenger_run(function($u){$id=(int)($_GET['id']??0);MessengerSecurity::participant($id,(int)$u['id']);$c=Database::fetch('SELECT c.*,u.name owner_name FROM chat_conversations c LEFT JOIN users u ON u.id=c.owner_id WHERE c.id=? AND c.deleted_at IS NULL',[$id]);$c['participants']=Database::fetchAll('SELECT p.user_id,p.participant_role,p.can_send,p.is_muted,p.last_read_at,u.name,u.department,u.role_key FROM chat_participants p JOIN users u ON u.id=p.user_id WHERE p.conversation_id=? AND p.deleted_at IS NULL AND p.left_at IS NULL ORDER BY p.participant_role,u.name',[$id]);return $c;});
